package core

import (
	"encoding/json"
	"net"
	"os"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/metacubex/mihomo/listener"
	"github.com/metacubex/mihomo/tunnel/statistic"
)

// Status is the snapshot returned by GetStatus(). It is JSON-encoded before
// crossing the gomobile boundary because gomobile cannot bind struct fields
// directly.
//
// Field naming is camelCase to stay compatible with the Dart `Status` model
// generated by json_serializable on the Flutter side. Adding fields is safe
// (older clients ignore them); renaming or removing existing fields is a
// breaking change.
type Status struct {
	Running             bool      `json:"running"`
	StartedAtUnix       int64     `json:"startedAtUnix"`
	UptimeSeconds       int64     `json:"uptimeSeconds"`
	MihomoVersion       string    `json:"mihomoVersion"`
	NozeltVersion       string    `json:"nozeltCoreVersion"`
	Mode                string    `json:"mode"`             // "rule" | "global" | "direct" | ""
	Listeners           Listeners `json:"listeners"`        // open inbound ports (0 = not bound)
	ConnectionsCount    int       `json:"connectionsCount"` // active tracked connections
	Tun                 TunStatus `json:"tun"`              // TUN interface state
	OpenFileDescriptors int       `json:"openFileDescriptors"`
	GoRoutines          int       `json:"goRoutines"`
	SocketProtection    bool      `json:"socketProtection"`
	ProtectedSockets    uint64    `json:"protectedSockets"`
	ProtectionFailures  uint64    `json:"protectionFailures"`
}

// Listeners is the set of inbound ports actually open right now, sourced
// from mihomo's listener.GetPorts(). A zero value means that listener type
// is not bound (either disabled in config or failed to open).
type Listeners struct {
	MixedPort  int `json:"mixedPort"`
	HTTPPort   int `json:"httpPort"`
	SocksPort  int `json:"socksPort"`
	RedirPort  int `json:"redirPort"`
	TProxyPort int `json:"tproxyPort"`
}

// TunStatus reports whether mihomo's TUN listener is up and, if so, which
// stack it runs on and which file descriptor it adopted. Sourced from
// mihomo's listener.GetTunConf(). Enabled is false whenever the engine is
// stopped or the TUN failed to start.
type TunStatus struct {
	Enabled bool   `json:"enabled"`
	Stack   string `json:"stack"` // "gvisor" | "system" | "mixed" | ""
	Fd      int    `json:"fd"`    // adopted Android descriptor, 0 when none
}

// Traffic is the snapshot returned by GetTraffic(): cumulative byte counters
// plus the most recent up/down speed sample. All values are bytes/sec for
// speeds and bytes for totals.
//
// `Synthetic` is always false now that mihomo's real statistic manager is
// wired in. The field is kept (and explicitly serialized) so the Kotlin
// TrafficStreamHandler can distinguish "Go reports real numbers" from
// "Go reports nothing" and skip the legacy fake generator.
type Traffic struct {
	UploadBytes      int64 `json:"uploadBytes"`
	DownloadBytes    int64 `json:"downloadBytes"`
	UploadSpeedBps   int64 `json:"uploadSpeedBps"`
	DownloadSpeedBps int64 `json:"downloadSpeedBps"`
	ActiveConns      int   `json:"activeConnections"`
	Synthetic        bool  `json:"synthetic"`
}

// ConnectionSnapshot is the desktop dashboard representation of one live
// mihomo tracker. It intentionally stays in memory and is returned only on an
// explicit UI request; Nozelt never writes destinations or process names to
// disk. Android currently consumes only the aggregate count in Status.
type ConnectionSnapshot struct {
	ID          string   `json:"id"`
	Network     string   `json:"network"`
	InboundType string   `json:"inboundType"`
	Source      string   `json:"source"`
	Destination string   `json:"destination"`
	Host        string   `json:"host"`
	Process     string   `json:"process"`
	Upload      int64    `json:"upload"`
	Download    int64    `json:"download"`
	StartedAt   int64    `json:"startedAt"`
	Chains      []string `json:"chains"`
	Rule        string   `json:"rule"`
	RulePayload string   `json:"rulePayload"`
}

// GetStatusJSON returns the current core status encoded as JSON. The encoded
// form is what the binding hands back to Kotlin.
func GetStatusJSON() string {
	st := snapshotStatus()
	out, err := json.Marshal(st)
	if err != nil {
		// Marshalling a struct with only primitive fields cannot realistically
		// fail; if it ever does we return a parseable error envelope so the
		// host does not crash on a JSON decode.
		return `{"error":"status encode failed"}`
	}
	return string(out)
}

// GetTrafficJSON returns live traffic counters as JSON. Returns zeroed
// counters when the core is not running.
func GetTrafficJSON() string {
	tr := snapshotTraffic()
	out, err := json.Marshal(tr)
	if err != nil {
		return `{"error":"traffic encode failed"}`
	}
	return string(out)
}

// GetConnectionsJSON returns a bounded live-only connection list for the
// desktop UI. A stopped engine returns an empty array.
func GetConnectionsJSON() string {
	connections := make([]ConnectionSnapshot, 0)
	if IsRunning() {
		statistic.DefaultManager.Range(func(tracker statistic.Tracker) bool {
			info := tracker.Info()
			if info == nil || info.Metadata == nil {
				return true
			}
			metadata := info.Metadata
			host := metadata.Host
			if host == "" {
				host = metadata.SniffHost
			}
			destinationHost := host
			if destinationHost == "" && metadata.DstIP.IsValid() {
				destinationHost = metadata.DstIP.String()
			}
			destination := destinationHost
			if destinationHost != "" && metadata.DstPort != 0 {
				destination = net.JoinHostPort(
					destinationHost,
					strconv.FormatUint(uint64(metadata.DstPort), 10),
				)
			}
			connections = append(connections, ConnectionSnapshot{
				ID:          tracker.ID(),
				Network:     metadata.NetWork.String(),
				InboundType: metadata.Type.String(),
				Source:      metadata.SourceAddress(),
				Destination: destination,
				Host:        host,
				Process:     metadata.Process,
				Upload:      info.UploadTotal.Load(),
				Download:    info.DownloadTotal.Load(),
				StartedAt:   info.Start.UnixMilli(),
				Chains:      append([]string(nil), info.Chain...),
				Rule:        info.Rule,
				RulePayload: info.RulePayload,
			})
			return len(connections) < 2048
		})
	}
	sort.Slice(connections, func(i, j int) bool {
		return connections[i].StartedAt > connections[j].StartedAt
	})
	out, err := json.Marshal(connections)
	if err != nil {
		return `[]`
	}
	return string(out)
}

// CloseConnection closes one live tracker by its opaque UUID. It contains no
// endpoint data and is safe to cross the desktop FFI boundary.
func CloseConnection(id string) bool {
	if id == "" {
		return false
	}
	tracker := statistic.DefaultManager.Get(id)
	if tracker == nil {
		return false
	}
	return tracker.Close() == nil
}

// CloseAllConnections drains every currently tracked connection.
func CloseAllConnections() int {
	closed := 0
	statistic.DefaultManager.Range(func(tracker statistic.Tracker) bool {
		if tracker.Close() == nil {
			closed++
		}
		return true
	})
	return closed
}

const embeddedMihomoModuleVersion = "1.19.32"

// MihomoVersion returns the pinned Go module release embedded in this binary.
// Mihomo's constant.Version currently describes an internal core/API generation
// ("1.10.0"), not the tagged module release. The test suite keeps this display
// value synchronized with go.mod whenever the dependency is upgraded.
func MihomoVersion() string {
	return embeddedMihomoModuleVersion
}

func snapshotStatus() Status {
	running := IsRunning()
	started := startedAt()
	protectionEnabled, protectedSockets, protectionFailures := socketProtectionStatus()

	st := Status{
		Running:             running,
		MihomoVersion:       MihomoVersion(),
		NozeltVersion:       NozeltCoreVersion,
		OpenFileDescriptors: countOpenFileDescriptors(),
		GoRoutines:          runtime.NumGoroutine(),
		SocketProtection:    protectionEnabled,
		ProtectedSockets:    protectedSockets,
		ProtectionFailures:  protectionFailures,
	}

	if running {
		if !started.IsZero() {
			st.UptimeSeconds = int64(time.Since(started).Seconds())
			st.StartedAtUnix = started.Unix()
		}

		if cfg := currentConfig(); cfg != nil && cfg.General != nil {
			st.Mode = cfg.General.Mode.String()
		}

		ports := listener.GetPorts()
		if ports != nil {
			st.Listeners = Listeners{
				MixedPort:  ports.MixedPort,
				HTTPPort:   ports.Port,
				SocksPort:  ports.SocksPort,
				RedirPort:  ports.RedirPort,
				TProxyPort: ports.TProxyPort,
			}
		}

		// statistic.DefaultManager.Snapshot() walks the live tracker map; we
		// only need the connection count here so we use the cheaper Range.
		var conns int
		statistic.DefaultManager.Range(func(_ statistic.Tracker) bool {
			conns++
			return true
		})
		st.ConnectionsCount = conns

		// TUN state straight from mihomo's live listener config. Enabled is
		// true only when the sing-tun listener actually came up; when it is
		// down we blank the stack/fd so the status does not advertise a
		// gvisor default that is not really running.
		tc := listener.GetTunConf()
		if tc.Enable {
			// mihomo's Stack.String() is display-cased ("gVisor"/"System"/
			// "Mixed"); the config vocabulary and the Dart side both use
			// lowercase, so normalise to one form here.
			st.Tun = TunStatus{
				Enabled: true,
				Stack:   strings.ToLower(tc.Stack.String()),
				Fd:      tc.FileDescriptor,
			}
		}
	}

	return st
}

func countOpenFileDescriptors() int {
	entries, err := os.ReadDir("/proc/self/fd")
	if err != nil {
		return -1
	}
	return len(entries)
}

func snapshotTraffic() Traffic {
	if !IsRunning() {
		return Traffic{} // zero value implies Synthetic=false too
	}

	up, down := statistic.DefaultManager.Now()
	totalUp, totalDown := statistic.DefaultManager.Total()

	var conns int
	statistic.DefaultManager.Range(func(_ statistic.Tracker) bool {
		conns++
		return true
	})

	return Traffic{
		UploadBytes:      totalUp,
		DownloadBytes:    totalDown,
		UploadSpeedBps:   up,
		DownloadSpeedBps: down,
		ActiveConns:      conns,
		Synthetic:        false,
	}
}
